css:
.tpl-premium *{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.tpl-premium :root{--pur:#5A2A9B;--ink:#3B2278;--mag:#D3217B;--org:#F28A1B;--gold:#E5A91A;--teal:#0E9AA0;--blue:#2A6FD6;--grn:#35A653}
.tpl-premium,.tpl-premium{width:210mm;height:297mm}
.tpl-premium{font-family:Poppins,sans-serif;color:var(--ink)}
.tpl-premium .page{position:relative;width:210mm;height:297mm;overflow:hidden;
 background:
  radial-gradient(circle at 0% 0%,#FFD6E8 0,transparent 38%),
  radial-gradient(circle at 100% 0%,#FFE9B8 0,transparent 36%),
  radial-gradient(circle at 100% 100%,#C9EEF0 0,transparent 40%),
  radial-gradient(circle at 0% 100%,#E2D4F8 0,transparent 40%),
  linear-gradient(180deg,#FFFDF8,#FFF7EC)}
/* dual boxed border */
.tpl-premium .b1{position:absolute;inset:4.5mm;border:2.6mm solid transparent;border-image:linear-gradient(135deg,#D3217B,#F28A1B,#E5A91A,#35A653,#0E9AA0,#2A6FD6,#5A2A9B) 1;}
.tpl-premium .b2{position:absolute;inset:9.6mm;border:.9mm solid #E5A91A;box-shadow:inset 0 0 0 1.1mm #FFFDF8,inset 0 0 0 1.5mm #D3217B}
.tpl-premium .corner{position:absolute;width:22mm;height:22mm;z-index:5}
.tpl-premium .c-tl{left:3mm;top:3mm} .tpl-premium .c-tr{right:3mm;top:3mm;transform:scaleX(-1)} .tpl-premium .c-bl{left:3mm;bottom:3mm;transform:scaleY(-1)} .tpl-premium .c-br{right:3mm;bottom:3mm;transform:scale(-1,-1)}
.tpl-premium .content{position:absolute;left:17mm;right:17mm;top:15mm;bottom:15mm;display:flex;flex-direction:column;align-items:center}
.tpl-premium .url{font:700 5.6pt Poppins;letter-spacing:.55em;color:var(--mag)}
.tpl-premium .ribbon{margin-top:2.4mm;position:relative;padding:2.1mm 11mm;color:#fff;font:700 8.2pt Poppins;letter-spacing:.16em;
 background:linear-gradient(90deg,#D3217B,#F28A1B 55%,#E5A91A);border-radius:9mm;box-shadow:0 1.2mm 2.5mm rgba(211,33,123,.35),inset 0 0 0 .5mm rgba(255,255,255,.6)}
.tpl-premium .ribbon:before,.tpl-premium .ribbon:after{content:"";position:absolute;top:50%;width:14mm;height:.5mm;background:linear-gradient(90deg,transparent,#E5A91A)}
.tpl-premium .ribbon:before{right:100%;margin-right:3mm} .tpl-premium .ribbon:after{left:100%;margin-left:3mm;transform:scaleX(-1)}
.tpl-premium .kick{margin-top:3mm;font:700 9.5pt Poppins;letter-spacing:.55em;color:var(--org);padding-left:.55em}
.tpl-premium .title{font:700 46pt/1 Lora,serif;letter-spacing:.04em;margin-top:-.5mm;
 background:linear-gradient(100deg,#5A2A9B 0%,#D3217B 45%,#F28A1B 80%,#E5A91A 100%);-webkit-background-clip:text;background-clip:text;color:transparent;
 filter:drop-shadow(0 .6mm .5mm rgba(229,169,26,.55))}
.tpl-premium .div{display:flex;align-items:center;gap:2mm;margin-top:1.6mm}
.tpl-premium .div i{display:block;width:30mm;height:.5mm;background:linear-gradient(90deg,transparent,#E5A91A)} .tpl-premium .div i:last-child{transform:scaleX(-1)}
.tpl-premium .div b{width:2.4mm;height:2.4mm;background:var(--mag);transform:rotate(45deg);box-shadow:0 0 0 .6mm #FFD34D}
.tpl-premium .ded{margin-top:3mm;padding:1.9mm 9mm;color:#fff;font:700 7.8pt Poppins;letter-spacing:.17em;border-radius:1.2mm;
 background:linear-gradient(90deg,#0E9AA0,#2A6FD6);box-shadow:0 1mm 2mm rgba(14,154,160,.35),inset 0 0 0 .45mm rgba(255,255,255,.7)}
.tpl-premium .photo{position:relative;margin-top:2mm;width:64mm;height:60mm;display:flex;align-items:center;justify-content:center}
.tpl-premium .photo svg.laurel{position:absolute;inset:-1mm 0;width:100%;height:calc(100% + 2mm)}
.tpl-premium .ring{width:45mm;height:45mm;border-radius:50%;padding:1.5mm;background:conic-gradient(#D3217B,#F28A1B,#E5A91A,#35A653,#0E9AA0,#2A6FD6,#5A2A9B,#D3217B);
 box-shadow:0 1.5mm 4mm rgba(90,42,155,.35)}
.tpl-premium .ring2{width:100%;height:100%;border-radius:50%;padding:1mm;background:#fff}
.tpl-premium .ph{width:100%;height:100%;border-radius:50%;background:radial-gradient(circle at 50% 30%,#F7EFFF,#DCCBF5);display:flex;align-items:flex-end;justify-content:center;overflow:hidden;position:relative}
.tpl-premium .ph svg{width:78%;height:78%} .tpl-premium .ph span{position:absolute;bottom:4mm;font:700 4.8pt Poppins;letter-spacing:.18em;color:var(--pur)}
.tpl-premium .sp{position:absolute;width:5mm;height:5mm} .tpl-premium .sp svg{width:100%;height:100%}
.tpl-premium .name{position:relative;z-index:2;padding:2.2mm 16mm;color:#fff;font:700 19pt Lora,serif;letter-spacing:.06em;
 background:linear-gradient(90deg,#5A2A9B,#8A3FC0 50%,#D3217B);box-shadow:0 1.2mm 3mm rgba(90,42,155,.4),inset 0 0 0 .5mm #E5A91A,inset 0 0 0 1mm #5A2A9B,inset 0 0 0 1.3mm rgba(255,211,77,.8)}
.tpl-premium .nw{position:relative;margin-top:1mm}
.tpl-premium .nw .tl,.tpl-premium .nw .tr{position:absolute;top:3.4mm;width:11mm;height:100%;background:linear-gradient(90deg,#3E1D78,#6A35B5)}
.tpl-premium .nw .tl{right:calc(100% - 4mm);clip-path:polygon(0 0,100% 0,100% 100%,0 100%,28% 50%)}
.tpl-premium .nw .tr{left:calc(100% - 4mm);clip-path:polygon(0 0,100% 0,72% 50%,100% 100%,0 100%)}
.tpl-premium .name{margin-top:0;z-index:2}
.tpl-premium .tag{margin-top:3.2mm;font:700 8.2pt Poppins;letter-spacing:.3em;color:var(--teal);padding-left:.3em}
.tpl-premium .hh{margin-top:2.4mm;display:flex;align-items:center;gap:3mm;font:italic 700 17pt Lora,serif;color:var(--mag)}
.tpl-premium .hh i{display:block;width:34mm;height:.5mm;background:linear-gradient(90deg,transparent,#0E9AA0)} .tpl-premium .hh i:last-child{transform:scaleX(-1)}
.tpl-premium .card{margin-top:1.6mm;width:100%;position:relative;padding:3.4mm 11mm 2.6mm;background:rgba(255,255,255,.92);border:.6mm solid #D3217B;
 box-shadow:inset 0 0 0 1mm #fff,inset 0 0 0 1.35mm #E5A91A,0 1.2mm 3mm rgba(211,33,123,.18);text-align:center}
.tpl-premium .card p{font:400 8.6pt/1.46 Lora,serif;color:#3B2278;margin-bottom:1.3mm}
.tpl-premium .card p.lead{font-weight:600}
.tpl-premium .card p.end{font:italic 700 10pt Lora,serif;color:var(--mag);margin:0}
.tpl-premium .foot{position:absolute;left:0;right:0;bottom:0;display:flex;flex-direction:column;align-items:center}
.tpl-premium .fl{font:700 7.2pt Poppins;letter-spacing:.18em;color:var(--teal)}
.tpl-premium .ft{margin-top:1.2mm;font:500 6.2pt Poppins;letter-spacing:.3em;color:var(--pur)}
.tpl-premium .cv{font:700 30pt/1 Lora,serif;letter-spacing:.1em;margin-top:.8mm;background:linear-gradient(90deg,#D3217B,#F28A1B,#E5A91A,#35A653,#0E9AA0,#2A6FD6,#5A2A9B);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 .4mm .3mm rgba(90,42,155,.3))}
.tpl-premium .cy{margin-top:.8mm;font:700 6.6pt Poppins;letter-spacing:.18em;color:var(--org)}
.tpl-premium .og{margin-top:2mm;font:700 5.6pt Poppins;letter-spacing:.35em;color:var(--mag)}
.tpl-premium .chips{margin-top:1.4mm;display:flex;justify-content:center;gap:1.6mm}
.tpl-premium .chip{color:#fff;font:700 6.6pt Poppins;padding:1.1mm 3.2mm;border-radius:5mm;box-shadow:0 .5mm 1mm rgba(90,42,155,.3),inset 0 0 0 .35mm rgba(255,255,255,.75)}
.tpl-premium .q{margin-top:2mm;font:italic 600 7.6pt Lora,serif;color:var(--pur)}
.tpl-premium .ph{position:relative}.tpl-premium .ph img.pimg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;border-radius:50%}
.tpl-premium .role{margin-top:2.6mm;padding:1.1mm 7mm;border-radius:4mm;color:#fff;font:700 9pt Poppins;letter-spacing:.12em;background:linear-gradient(90deg,#0E9AA0,#2A6FD6);box-shadow:0 .8mm 2mm rgba(14,154,160,.35),inset 0 0 0 .4mm rgba(255,255,255,.7)}
